/// Scenarios that also ship the whole 64-bit system a full image has
/// (`system_modules`): installers whose product's own programs import
/// what they will (office_install: ODT starts the 64-bit
/// OfficeClickToRun.exe, whose imports are only seen in the run).
const FULL_SYSTEM_SCENARIOS: &[&str] = &[
    "office_install",
    "office_install_gui",
    "office_install_local",
    "office_word",
    "office_excel",
];

/// A scenario's kernel command line as its image has it.
fn scenario_cmdline(s: &Scenario) -> String {
    let screen = match scenario_boot(s.name) {
        Boot::Uefi => "",
        // The firmware gives no framebuffer on `virt`: the kernel drives
        // the virtio-gpu (`aarch64_display`).
        Boot::UefiAarch64 if aarch64_display(s.name) => " display=virtio",
        _ => " noscreen",
    };
    format!("{}{screen}{}", s.cmdline, events_flag())
}

/// Whether aarch64 scenario `name` needs a screen: its screen check takes
/// screendumps (a desktop presented to memory, `presenter=test`, needs
/// none). QEMU `virt`'s firmware gives no framebuffer to take (and Limine
/// refuses ramfb's: it lies in memory the firmware will not let go), so
/// such a machine gets a virtio-gpu and its kernel `display=virtio`.
fn aarch64_display(name: &str) -> bool {
    scenario_boot(name) == Boot::UefiAarch64
        && screen_check(name).is_some()
        && scenarios()
            .iter()
            .find(|s| s.name == name)
            .is_some_and(|s| !s.cmdline.contains("presenter=test"))
}

/// A boot module: (file, directory in the image).
type Module = (&'static str, &'static str);

/// glibc's (and the Wayland client library's) files and places on x86-64
/// and their aarch64 counterparts, which a twin ships instead: the program interpreter where PT_INTERP names it
/// (`/lib64/ld-linux-x86-64.so.2`, `/lib/ld-linux-aarch64.so.1`) and in
/// the multiarch system directory, libc and libm there.
const GLIBC_ARM64: &[(Module, Module)] = &[
    (
        ("target/prebuilt/glibc/ld-linux-x86-64.so.2", "lib64"),
        ("target/prebuilt/glibc-arm64/ld-linux-aarch64.so.1", "lib"),
    ),
    (
        ("target/prebuilt/glibc/ld-linux-x86-64.so.2", "lib/x86_64-linux-gnu"),
        ("target/prebuilt/glibc-arm64/ld-linux-aarch64.so.1", "lib/aarch64-linux-gnu"),
    ),
    (
        ("target/prebuilt/glibc/libc.so.6", "lib/x86_64-linux-gnu"),
        ("target/prebuilt/glibc-arm64/libc.so.6", "lib/aarch64-linux-gnu"),
    ),
    (
        ("target/prebuilt/glibc/libm.so.6", "lib/x86_64-linux-gnu"),
        ("target/prebuilt/glibc-arm64/libm.so.6", "lib/aarch64-linux-gnu"),
    ),
    (
        ("target/prebuilt/libwayland-client/libwayland-client.so.0", "lib/x86_64-linux-gnu"),
        ("target/prebuilt/libwayland-client-arm64/libwayland-client.so.0", "lib/aarch64-linux-gnu"),
    ),
    (
        ("target/prebuilt/libffi/libffi.so.8", "lib/x86_64-linux-gnu"),
        ("target/prebuilt/libffi-arm64/libffi.so.8", "lib/aarch64-linux-gnu"),
    ),
    // The scripts' busybox (the batch scenarios' checksums): Alpine's
    // static aarch64 one, under busybox.net's x86_64 one's name.
    (
        ("target/prebuilt/busybox-linux/busybox", "lx"),
        ("target/prebuilt/busybox-linux-aarch64/busybox.static@busybox", "lx"),
    ),
];

/// The boot modules (file, directory) scenario `name` ships besides the
/// test programs.
fn extra_modules(name: &str) -> Vec<(&'static str, &'static str)> {
    // A twin ships its x64 scenario's files (their ARM64 builds), glibc's
    // as aarch64's (GLIBC_ARM64).
    if let Some(base) = twin_base(name) {
        let mut modules = extra_modules(base);
        for m in &mut modules {
            if let Some((_, arm)) = GLIBC_ARM64.iter().find(|(x64, _)| x64 == m) {
                *m = *arm;
            } else if let Some(arm) = linux_root_arm64(m.0) {
                // A Linux root's tree: the root assembled from the
                // packages' arm64 builds (`<name>-arm64`).
                m.0 = arm;
            }
        }
        modules.sort_unstable();
        modules.dedup();
        return modules;
    }
    let mut sets: Vec<&str> = MODULE_SETS.iter().filter(|s| s.0 == name).map(|s| s.1).collect();
    if sets.is_empty() {
        sets.push(name);
    }
    let mut modules: Vec<_> =
        EXTRA_MODULES.iter().filter(|m| sets.contains(&m.0)).map(|m| (m.1, m.2)).collect();
    // kernelbase is part of the system wherever kernel32 is, as on
    // Windows: it hosts the core API sets (ARCHITECTURE "API sets").
    for (kernel32, kernelbase, dir) in [
        ("kernel32.dll", "kernelbase.dll", "Windows/System32"),
        ("x86/kernel32.dll", "x86/kernelbase.dll", "Windows/SysWOW64"),
    ] {
        if modules.contains(&(kernel32, dir)) {
            modules.push((kernelbase, dir));
        }
    }
    if FULL_SYSTEM_SCENARIOS.contains(&name) {
        modules.extend(system_modules());
    }
    // What those modules import, so the set is closed: a DLL whose
    // dependency is not in the image does not load, and the program dies
    // of a module nobody listed. gala's DLLs carry Windows' own
    // dependencies where a program can see them (ARCHITECTURE "The
    // module graph"), so this follows the import tables of the DLLs
    // themselves (`static_imports`, from the checked-in copies) rather
    // than a second list to keep in step with them. The 32-bit set
    // (`x86/`, SysWOW64) stays as listed: its names are written with the
    // prefix. A dependency neither checked in nor built is left out; the
    // load then fails in the guest, where the loader records the name
    // (`missing dll`).
    let mut i = 0;
    while i < modules.len() {
        let (file, _) = modules[i];
        i += 1;
        if file.contains('/') {
            continue;
        }
        for dep in static_imports(file) {
            // Dependencies live where the system's DLLs do, whatever
            // directory the importer was put in (a test DLL in C:\gala
            // imports kernel32 from System32).
            if !modules.contains(&(dep, "Windows/System32")) {
                modules.push((dep, "Windows/System32"));
            }
        }
    }
    modules.sort_unstable();
    modules.dedup();
    modules
}

/// Where the checked-in copy of the USER_DLLS file `file` is: user/bin
/// holds it under its exported name, and `export-tests` keeps it equal to
/// the build's (CI checks they match). This is the copy gala-um ships, and
/// the one every checkout has whether or not the DLLs are built, so what
/// a module set is read from does not depend on what was built before it.
fn shipped_dll(file: &str) -> PathBuf {
    match USER_DLLS.iter().find(|d| d.file == file) {
        Some(d) => root().join("user/bin").join(d.exported_as),
        None => built_dll(file),
    }
}

/// The DLLs of `file`'s import table that gala builds itself (by their
/// USER_DLLS names): what has to be in the image for it to load. Read from
/// the checked-in copy (`shipped_dll`), never from the build, so a clean
/// tree closes the set exactly as a built one does: reading the build
/// instead left every set open where nothing was built yet, which took the
/// 23 gala-um programs that load advapi32 and its kin with it. Empty if
/// the file is neither checked in nor built, or is no PE.
fn static_imports(file: &str) -> Vec<&'static str> {
    let Ok(image) = fs::read(shipped_dll(file)) else {
        return Vec::new();
    };
    let names = import_names(&image);
    USER_DLLS
        .iter()
        .filter(|d| names.iter().any(|n| n.eq_ignore_ascii_case(d.file)))
        .map(|d| d.file)
        .collect()
}

/// The DLL names in a PE's import directory (empty if it has none or the
/// file is not one: every read is checked, so a truncated or odd file
/// gives nothing instead of a panic).
fn import_names(image: &[u8]) -> Vec<String> {
    let at32 = |o: usize| -> Option<usize> {
        Some(u32::from_le_bytes(image.get(o..o + 4)?.try_into().ok()?) as usize)
    };
    let at16 = |o: usize| -> Option<u16> {
        Some(u16::from_le_bytes(image.get(o..o + 2)?.try_into().ok()?))
    };
    let names = || -> Option<Vec<String>> {
        let pe = at32(0x3c)?;
        if image.get(pe..pe + 4)? != b"PE\0\0" {
            return None;
        }
        let sections = pe + 24 + usize::from(at16(pe + 20)?);
        // DataDirectory[1] (imports) of a PE32+ or PE32 optional header.
        let dirs = pe + 24 + if at16(pe + 24)? == 0x20b { 112 } else { 96 };
        let rva = at32(dirs + 8)?;
        if rva == 0 {
            return None;
        }
        // A section's file offset for an address in it (the image on disk
        // is not laid out as it is in memory).
        let offset = |rva: usize| -> Option<usize> {
            (0..usize::from(at16(pe + 6)?)).find_map(|i| {
                let s = sections + i * 40;
                let (va, vs) = (at32(s + 12)?, at32(s + 8)?);
                let (raw, rs) = (at32(s + 20)?, at32(s + 16)?);
                if va <= rva && rva < va + vs.max(rs) { Some(raw + (rva - va)) } else { None }
            })
        };
        let mut out = Vec::new();
        let mut desc = offset(rva)?;
        loop {
            // The Name of an IMPORT_DESCRIPTOR (20 bytes); 0 ends the table.
            let name = at32(desc + 12)?;
            if name == 0 {
                return Some(out);
            }
            let at = offset(name)?;
            let end = at + image.get(at..)?.iter().position(|&b| b == 0)?;
            out.push(String::from_utf8_lossy(&image[at..end]).into_owned());
            desc += 20;
        }
    };
    names().unwrap_or_default()
}

/// `(program file, args)` if the scenario can share a VM: it only runs one
/// program (no other kernel flags), expects success, boots by BIOS (or is
/// the aarch64 kernel's: those share VMs of their own), and
/// expects nothing that depends on running first (process ids, a
/// session's desktop going live: logged once per boot).
fn batchable(s: &Scenario) -> Option<(&'static str, &'static str)> {
    if s.exit_status != QEMU_EXIT_SUCCESS
        || !matches!(scenario_boot(s.name), Boot::Bios | Boot::UefiAarch64)
        || s.expect.iter().any(|e| e.contains("pid ") || e.starts_with("desktop: session "))
        // A screen check drives and reads its own machine.
        || screen_check(s.name).is_some()
        || net_marker(s.name).is_some()
        || host_page_scenario(s.name)
        || disk_scenario(s.name).is_some()
        || s.name.starts_with("onecpu_")
        || s.name.starts_with("arm_onecpu_")
        // A scenario that snapshots and resumes itself is one machine's
        // (in a batch it would take no snapshot and run none of its
        // resumes, and still pass).
        || SNAPSHOT_SCENARIOS.iter().any(|p| p.name == s.name)
    {
        return None;
    }
    let (mut program, mut args) = (None, "");
    for word in s.cmdline.split_whitespace() {
        match word.split_once('=') {
            _ if word == "qemu_exit" => {}
            Some(("run", p)) if !p.contains(',') => program = Some(p),
            Some(("args", a)) if !a.contains(',') => args = a,
            _ => return None,
        }
    }
    program.map(|p| (p, args))
}

/// Groups the selected scenarios into VMs: batchable ones with identical
/// boot modules share VMs (spread over the host CPUs), the rest boot alone.
fn plan_vms<'a>(selected: &[&'a Scenario]) -> Vec<Vm<'a>> {
    use std::collections::BTreeMap;
    // Grouped by architecture (aarch64 or not) and boot modules: a VM is
    // one kernel's.
    type Group = (bool, Vec<(&'static str, &'static str)>);
    let mut groups: BTreeMap<Group, Vec<&Scenario>> = BTreeMap::new();
    let mut vms = Vec::new();
    for &s in selected {
        match batchable(s) {
            // Its own image, whose name picks the emulation (`qemu`).
            Some(_) if single_thread_tcg(s.name) => vms.push(Vm::Single(s)),
            Some(_) if env::var_os("XTASK_NO_BATCH").is_none() => groups
                .entry((is_aarch64_scenario(s.name), extra_modules(s.name)))
                .or_default()
                .push(s),
            _ => vms.push(Vm::Single(s)),
        }
    }
    let cpus = thread::available_parallelism().map_or(2, |n| n.get());
    let batched: usize = groups.values().map(Vec::len).sum();
    let size = batched.div_ceil(cpus).clamp(1, MAX_BATCH);
    for group in groups.into_values() {
        for chunk in group.chunks(size) {
            vms.push(match chunk {
                [one] => Vm::Single(one),
                _ => Vm::Batch(chunk.to_vec()),
            });
        }
    }
    vms
}

/// `XTASK_SHARD=i/n` (1-based): only every n-th VM, starting at the i-th,
/// so n machines boot the whole set between them (CI's boot jobs). The VMs
/// are dealt out after `plan_vms`, so a batch stays in one shard; the
/// shard says what it took.
fn shard(vms: Vec<Vm<'_>>) -> Result<Vec<Vm<'_>>> {
    let Ok(spec) = env::var("XTASK_SHARD") else {
        return Ok(vms);
    };
    let parsed = spec
        .split_once('/')
        .and_then(|(i, n)| Some((i.parse::<usize>().ok()?, n.parse::<usize>().ok()?)));
    let Some((i, n)) = parsed.filter(|&(i, n)| i >= 1 && i <= n) else {
        return Err(format!("XTASK_SHARD={spec:?}: expected i/n with 1 <= i <= n"));
    };
    let total = vms.len();
    let mine: Vec<Vm<'_>> =
        vms.into_iter().enumerate().filter(|(k, _)| k % n == i - 1).map(|(_, vm)| vm).collect();
    let scenarios: usize = mine
        .iter()
        .map(|vm| match vm {
            Vm::Single(_) => 1,
            Vm::Batch(group) => group.len(),
        })
        .sum();
    eprintln!("xtask: shard {i} of {n}: {} of {total} VMs ({scenarios} scenarios)", mine.len());
    Ok(mine)
}

fn boot_tests(release: bool, filter: Option<&String>) -> Result {
    RELEASE.store(release, std::sync::atomic::Ordering::Relaxed);
    let t0 = Instant::now();
    build_kernel(release)?;
    let built = t0.elapsed();
    // With `XTASK_REPEAT`, a scenario's exact name selects it alone (it
    // repeats one scenario: handover_upgrade's name is part of
    // handover_upgrade_uefi's); otherwise the filter is a substring.
    let exact = env::var_os("XTASK_REPEAT").is_some()
        && filter.is_some_and(|f| scenarios().iter().any(|s| s.name == f.as_str()));
    let selected: Vec<&Scenario> = scenarios()
        .iter()
        .filter(|s| match filter {
            // Pending and manual scenarios run only when named exactly.
            None => !named_only(s.name),
            Some(f) if exact => s.name == f.as_str(),
            // `name$`: that scenario only (`hello$`, not java_hello too).
            Some(f) if f.ends_with('$') => s.name == f.trim_end_matches('$'),
            // `a,b,c`: exactly these scenarios.
            Some(f) if f.contains(',') => f.split(',').any(|n| n == s.name),
            // A pending scenario runs when named exactly; others match
            // by substring.
            Some(f) => s.name == f.as_str() || (s.name.contains(f.as_str()) && !named_only(s.name)),
        })
        .collect();
    if selected.is_empty() {
        return Err("no boot test scenario matches the filter".into());
    }
    if selected.iter().any(|s| is_aarch64_scenario(s.name)) {
        build_kernel_aarch64(release)?;
    }
    if snapshot::request().is_some() && selected.len() != 1 {
        return Err(format!(
            "a machine snapshot is of one scenario; the filter selects {} (`name$` selects one)",
            selected.len()
        ));
    }
    if selected.iter().any(|s| SNAPSHOT_SCENARIOS.iter().any(|p| p.name == s.name)) {
        snapshot::want_digests();
    }
    let vms = shard(plan_vms(&selected))?;
    // Tests read the serial log; the screen console stays on only where
    // the scenario boots by UEFI, which keeps that code covered.
    let make = |vm: &Vm| match vm {
        Vm::Single(s) => make_iso(
            release,
            &format!("test-{}", s.name),
            &scenario_cmdline(s),
            &extra_modules(s.name),
        ),
        Vm::Batch(group) => {
            let (programs, args): (Vec<_>, Vec<_>) =
                group.iter().filter_map(|s| batchable(s)).unzip();
            let cmdline = format!(
                "qemu_exit noscreen{} run={} args={}",
                events_flag(),
                programs.join(","),
                args.join(",")
            );
            make_iso(
                release,
                &format!("batch-{}", group[0].name),
                &cmdline,
                &extra_modules(group[0].name),
            )
        }
    };
    if let Some(times) = env::var("XTASK_REPEAT").ok().and_then(|n| n.parse::<usize>().ok()) {
        let isos = run_parallel(&vms, |vm| make(vm));
        let isos: Vec<PathBuf> = isos.into_iter().collect::<Result<_>>()?;
        return repeat_boots(&vms, &isos, times);
    }
    // Each VM's image is made just before it boots and deleted after a
    // pass, so only the images of the VMs running at once are on the disk
    // (making them all first filled the disk: about 50 MB each).
    let iso_time = std::sync::Mutex::new(Duration::ZERO);
    let t2 = Instant::now();
    let results = run_parallel(&vms, |vm| {
        let t = Instant::now();
        let iso = make(vm)?;
        if let Ok(mut total) = iso_time.lock() {
            *total += t.elapsed();
        }
        let result = boot_vm(vm, &iso);
        // A passing VM's image is not needed again (a failed one is kept
        // to boot by hand), nor its disk image (a failed one's is kept to
        // look at: it says what it takes on the host).
        let disk = iso.with_extension("disk.img");
        let _ = fs::remove_file(snapshot::digests_path(&iso));
        // A snapshot took its own copy of the DLLs and maps; a hot swap's
        // plan was for this run only.
        let _ = fs::remove_dir_all(snapshot::modules_dir(&iso));
        let _ = fs::remove_file(iso.with_extension("hotswap.plan"));
        if result.1.iter().all(|(_, v)| v.is_ok()) {
            let _ = fs::remove_file(&iso);
            if !reuse_disk() {
                let _ = fs::remove_file(&disk);
            }
        } else if let Some(used) = host_usage_mib(&disk) {
            eprintln!(
                "xtask: kept {} ({used} MiB on the host; delete it when done)",
                disk.display()
            );
        }
        Ok(result)
    });
    let isos_made = iso_time.into_inner().unwrap_or_default();
    let booted = t2.elapsed();
    let mut failed = 0;
    let (mut firmware, mut kernel) = (Duration::ZERO, Duration::ZERO);
    let mut history = Vec::new();
    for (vm, result) in vms.iter().zip(results) {
        // A VM that could not be made or booted fails its scenarios (its
        // error was once dropped here, and the run passed without them).
        let (time, verdicts) = match result {
            Ok(r) => r,
            Err(e) => {
                let names: Vec<&str> = match vm {
                    Vm::Single(s) => vec![s.name],
                    Vm::Batch(group) => group.iter().map(|s| s.name).collect(),
                };
                for name in names {
                    failed += 1;
                    eprintln!("xtask: boot test {name:<20} FAILED: {e}");
                    history.push(HistoryRun {
                        scenario: name,
                        ok: false,
                        secs: 0.0,
                        shared: false,
                        reason: e.to_string(),
                    });
                }
                continue;
            }
        };
        firmware += time.to_banner;
        kernel += time.total.saturating_sub(time.to_banner);
        let shared = matches!(vm, Vm::Batch(_));
        for (scenario, verdict) in &verdicts {
            history.push(HistoryRun {
                scenario: scenario.name,
                ok: verdict.is_ok(),
                secs: time.total.as_secs_f64(),
                shared,
                reason: verdict
                    .as_ref()
                    .err()
                    .map(|e| e.split(" (serial log: ").next().unwrap_or(e).to_string())
                    .unwrap_or_default(),
            });
        }
        for (scenario, verdict) in verdicts {
            match verdict {
                Ok(()) if shared => eprintln!("xtask: boot test {:<20} ok", scenario.name),
                Ok(()) => eprintln!(
                    "xtask: boot test {:<20} ok  ({:.1}s to kernel, {:.1}s in kernel)",
                    scenario.name,
                    time.to_banner.as_secs_f64(),
                    time.total.saturating_sub(time.to_banner).as_secs_f64()
                ),
                Err(e) => {
                    failed += 1;
                    eprintln!("xtask: boot test {:<20} FAILED: {e}", scenario.name);
                }
            }
        }
        if let Vm::Batch(group) = vm {
            eprintln!(
                "xtask:   (shared VM of {} programs: {:.1}s to kernel, {:.1}s in kernel)",
                group.len(),
                time.to_banner.as_secs_f64(),
                time.total.saturating_sub(time.to_banner).as_secs_f64()
            );
        }
    }
    let summary = format!(
        "build {:.1}s, ISOs {:.1}s summed, boots {:.1}s wall (with the ISOs) ({} scenarios in {} VMs; summed: {:.1}s firmware+bootloader, {:.1}s kernel)",
        built.as_secs_f64(),
        isos_made.as_secs_f64(),
        booted.as_secs_f64(),
        selected.len(),
        vms.len(),
        firmware.as_secs_f64(),
        kernel.as_secs_f64()
    );
    eprintln!("xtask: timing: {summary}");
    let _ = fs::create_dir_all(report_dir());
    let _ = write(&report_dir().join("timing.txt"), &format!("{summary}\n"));
    // The suite's health over runs: flaky and slower scenarios.
    record_history(&history);
    let names: Vec<&str> = selected.iter().map(|s| s.name).collect();
    let health = fs::read_to_string(history_path()).unwrap_or_default();
    for line in history_findings(&health, &names) {
        eprintln!("xtask: health: {line}");
    }
    if failed == 0 {
        Ok(())
    } else {
        Err(format!("{failed} of {} boot tests failed", selected.len()))
    }
}

/// One scenario's outcome for target/report/history.jsonl.
struct HistoryRun {
    scenario: &'static str,
    ok: bool,
    /// The VM's whole time (a shared VM's for each of its scenarios).
    secs: f64,
    shared: bool,
    reason: String,
}

fn history_path() -> PathBuf {
    report_dir().join("history.jsonl")
}

/// Runs kept in the history (older ones are dropped when it grows past
/// twice this).
const HISTORY_KEEP: usize = 20_000;

/// Appends this run's outcomes to target/report/history.jsonl (one JSON
/// line per scenario: time, commit, host load, outcome, duration).
fn record_history(runs: &[HistoryRun]) {
    if runs.is_empty() {
        return;
    }
    let t = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs());
    let commit = Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .current_dir(root())
        .output()
        .ok()
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .unwrap_or_default();
    let load = fs::read_to_string("/proc/loadavg")
        .ok()
        .and_then(|l| l.split_whitespace().next().map(str::to_string))
        .unwrap_or_else(|| "0".into());
    let mut text = String::new();
    for r in runs {
        let reason: String = r
            .reason
            .chars()
            .take(200)
            .map(|c| match c {
                '"' | '\\' => '\'',
                c if c.is_control() => ' ',
                c => c,
            })
            .collect();
        text += &format!(
            "{{\"t\":{t},\"commit\":\"{commit}\",\"load\":{load},\"scenario\":\"{}\",\"ok\":{},\"secs\":{:.1},\"shared\":{},\"reason\":\"{reason}\"}}\n",
            r.scenario, r.ok, r.secs, r.shared
        );
    }
    let path = history_path();
    let old = fs::read_to_string(&path).unwrap_or_default();
    let mut lines: Vec<&str> = old.lines().collect();
    if lines.len() > 2 * HISTORY_KEEP {
        lines.drain(..lines.len() - HISTORY_KEEP);
    }
    let mut all = lines.join("\n");
    if !all.is_empty() {
        all.push('\n');
    }
    all += &text;
    let _ = fs::create_dir_all(report_dir());
    let _ = fs::write(&path, all);
}

/// Runs of one scenario looked at for flakiness.
const HISTORY_WINDOW: usize = 30;

/// What the history says about `scenarios` (this run's): those that both
/// passed and failed in their last HISTORY_WINDOW runs (flaky, with the
/// last failure's reason), and those whose latest run (alone in its VM)
/// took over 1.5 times, and 10 s more than, the median of their previous
/// ten passes.
fn history_findings(history: &str, scenarios: &[&str]) -> Vec<String> {
    use std::collections::BTreeMap;
    use triage::field;
    // Per scenario: (ok, secs, shared, reason, load).
    type Run<'a> = (bool, f64, bool, &'a str, &'a str);
    let mut runs: BTreeMap<&str, Vec<Run>> = BTreeMap::new();
    for line in history.lines() {
        let Some(name) = field(line, "scenario") else { continue };
        let ok = field(line, "ok") == Some("true");
        let secs = field(line, "secs").and_then(|v| v.parse().ok()).unwrap_or(0.0);
        let shared = field(line, "shared") == Some("true");
        let reason = field(line, "reason").unwrap_or("");
        let load = field(line, "load").unwrap_or("?");
        runs.entry(name).or_default().push((ok, secs, shared, reason, load));
    }
    let mut out = Vec::new();
    for name in scenarios {
        let Some(all) = runs.get(name) else { continue };
        let recent = &all[all.len().saturating_sub(HISTORY_WINDOW)..];
        let failures = recent.iter().filter(|r| !r.0).count();
        if failures > 0 && failures < recent.len() {
            let last = recent.iter().rev().find(|r| !r.0).map_or("", |r| r.3);
            out.push(format!(
                "{name} is flaky: failed {failures} of its last {} runs (last failure: {})",
                recent.len(),
                last.chars().take(120).collect::<String>()
            ));
        }
        let Some((latest, earlier)) = all.split_last() else { continue };
        if latest.2 || !latest.0 {
            continue;
        }
        let mut passes: Vec<f64> =
            earlier.iter().rev().filter(|r| r.0 && !r.2).take(10).map(|r| r.1).collect();
        if passes.len() < 3 {
            continue;
        }
        passes.sort_by(f64::total_cmp);
        let median = passes[passes.len() / 2];
        if latest.1 > 1.5 * median && latest.1 - median > 10.0 {
            out.push(format!(
                "{name} is slower: {:.1}s against a median of {median:.1}s over its last {} \
                 passes (host load {})",
                latest.1,
                passes.len(),
                latest.4
            ));
        }
    }
    out
}

/// `XTASK_REPEAT=<n> cargo xtask boot-test <name>`: boots one scenario's
/// image `n` times, one VM per two host CPUs at once (`XTASK_REPEAT_JOBS`
/// sets how many; more load brings races out, and time limits too). Each boot has its own copy of the image (a hard
/// link) and log; a failed boot keeps its log as
/// `test-<name>.r<i>.serial.log` (its error report is printed), a passed
/// one is deleted. Ends with the count of failures.
fn repeat_boots(vms: &[Vm], isos: &[PathBuf], times: usize) -> Result {
    let ([vm @ Vm::Single(s)], [iso]) = (vms, isos) else {
        return Err("XTASK_REPEAT needs a filter that selects one scenario of its own VM".into());
    };
    let copies: Vec<PathBuf> = (0..times.max(1))
        .map(|i| {
            let copy = iso.with_extension(format!("r{i}.iso"));
            let _ = fs::remove_file(&copy);
            fs::hard_link(iso, &copy).or_else(|_| fs::copy(iso, &copy).map(drop))?;
            Ok(copy)
        })
        .collect::<std::io::Result<_>>()
        .map_err(|e| format!("copying {}: {e}", iso.display()))?;
    let t = Instant::now();
    // One VM per two host CPUs (each has two processors): more only
    // queue, and a JVM then runs into its scenario's time limit.
    let jobs = env::var("XTASK_REPEAT_JOBS")
        .ok()
        .and_then(|n| n.parse().ok())
        .unwrap_or_else(|| thread::available_parallelism().map_or(1, |n| n.get().div_ceil(2)));
    let results = run_parallel_on(jobs, &copies, |copy| {
        let (_, verdicts) = boot_vm(vm, copy);
        let verdict = verdicts.into_iter().next().map_or(Ok(()), |(_, v)| v);
        let _ = fs::remove_file(copy);
        // Each copy's firmware variable store (64 MiB for AAVMF's): many
        // copies fill a small disk, and booting one again makes its own.
        for vars in ["ovmf-vars.fd", "aavmf-vars.fd"] {
            let _ = fs::remove_file(copy.with_extension(vars));
        }
        match &verdict {
            Ok(()) => {
                let _ = fs::remove_file(copy.with_extension("serial.log"));
                let _ = fs::remove_file(copy.with_extension("events.jsonl"));
                eprintln!("xtask: repeat {}: ok", copy.display());
            }
            Err(e) => eprintln!(
                "xtask: repeat {}: FAILED: {e} (log {})",
                copy.display(),
                copy.with_extension("serial.log").display()
            ),
        }
        Ok(verdict)
    });
    let failed = results.iter().filter(|r| !matches!(r, Ok(Ok(())))).count();
    eprintln!(
        "xtask: {}: {failed} of {} boots failed ({:.0}s)",
        s.name,
        copies.len(),
        t.elapsed().as_secs_f64()
    );
    let _ = fs::remove_file(iso);
    if failed == 0 { Ok(()) } else { Err(format!("{failed} of {} boots failed", copies.len())) }
}

/// Runs `f` on every job, at most one per host CPU at a time (each job is
/// an emulator that needs a CPU: running them all at once starves them on
/// small CI machines). Results are in job order.
fn run_parallel<J: Sync, T: Send>(
    jobs: &[J],
    f: impl Fn(&J) -> Result<T> + Sync,
) -> Vec<Result<T>> {
    // `XTASK_VMS=<n>`: at most n at a time (a shared, busy host).
    let workers = env::var("XTASK_VMS").ok().and_then(|n| n.parse().ok()).filter(|&n| n > 0);
    run_parallel_on(
        workers.unwrap_or_else(|| thread::available_parallelism().map_or(2, |n| n.get())),
        jobs,
        f,
    )
}

/// `run_parallel` with at most `workers` jobs at a time.
fn run_parallel_on<J: Sync, T: Send>(
    workers: usize,
    jobs: &[J],
    f: impl Fn(&J) -> Result<T> + Sync,
) -> Vec<Result<T>> {
    use std::sync::Mutex;
    use std::sync::atomic::{AtomicUsize, Ordering};
    let workers = workers.clamp(1, jobs.len().max(1));
    let next = AtomicUsize::new(0);
    let results: Mutex<Vec<Option<Result<T>>>> = Mutex::new(jobs.iter().map(|_| None).collect());
    thread::scope(|scope| {
        for _ in 0..workers {
            scope.spawn(|| {
                loop {
                    let i = next.fetch_add(1, Ordering::Relaxed);
                    let Some(job) = jobs.get(i) else { break };
                    let result = f(job);
                    if let Ok(mut r) = results.lock() {
                        r[i] = Some(result);
                    }
                }
            });
        }
    });
    results
        .into_inner()
        .unwrap_or_default()
        .into_iter()
        .map(|r| r.unwrap_or_else(|| Err("did not run".into())))
        .collect()
}

